list_dashboards.code:
var response = await client.Dashboards.ListDashboardsAsync();
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
foreach (var dashboard in ((IReadOnlyList<object?>)body["dashboards"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{dashboard["id"]} {dashboard["name"]} {dashboard["default"]}");

