var response = await client.Dashboards.GetDashboardAsync("3f2b8c1e-7a4d-4e29-9b1a-5c6d7e8f9a01");
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
Console.WriteLine($"{body["id"]} {body["name"]} {body["default"]}");
foreach (var section in ((IReadOnlyList<object?>)body["standard_sections"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{section["key"]} {section["visible"]}");
